/**
 * The entity catalog of the starter set (decision 0033, items 8 to 10): every
 * kind of the product's life cycle, in two levels — an area, its subgroups, the
 * kinds — with what each kind is, the standard or document it was taken from,
 * the ways it can be acquired, whether the engine makes one yet, the relations
 * it may carry and its template policy.
 *
 * This is starter content, not engine behaviour: `madarch new` writes it into
 * `madarch/kinds.yaml`, and from the first commit it is the product's own data,
 * which the wiki reads and the engine holds none of. A kind whose page exists
 * carries its page's template, its source and its labels; a kind the engine
 * cannot make yet carries neither, and the wiki shows nothing for it (the
 * template policy `none`).
 *
 * The rows are data: adding an area, a subgroup or a kind is an edit here, and
 * the catalog check of the starter set validates whatever the rows say.
 */

/** The two levels of the catalog: an area, and a subgroup of an area. */
export interface CatalogGroupData {
  readonly name: string;
  readonly en: string;
  readonly ru: string;
  /** The area the subgroup belongs to; absent for an area. */
  readonly parent?: string;
  /** Whether the navigation opens the area by itself (an area only). */
  readonly open?: boolean;
}

/** One kind of the catalog: the row every catalog kind declares, and the page fields a shown kind adds. */
export interface CatalogKindData {
  readonly name: string;
  /** The canonical concept id: one concept has one kind. */
  readonly id: string;
  /** The subgroup the kind belongs to. */
  readonly group: string;
  readonly definition: string;
  /** The addresses of the standards or documents the kind was taken from. */
  readonly sources: readonly string[];
  /** `extractor <id>`, or one of the catalog's origin marks. */
  readonly acquisition: readonly string[];
  readonly status: 'implemented' | 'partial' | 'not-implemented';
  readonly out: readonly string[];
  readonly into: readonly string[];
  readonly policy: 'page' | 'member' | 'none';
  readonly template?: string;
  readonly source?: 'graph' | 'markdown' | 'document';
  readonly origin?: 'agent' | 'person' | 'code' | 'history';
  readonly en?: readonly [string, string];
  readonly ru?: readonly [string, string];
  readonly describe?: readonly [string, string];
  readonly extra?: readonly string[];
}

/** The bound a subgroup holds, the marks, the statuses, the policies and the attributes the catalog declares about itself. */
export const CATALOG_SCHEMA = {
  'subgroup-kind-bound': 12,
  attributes: ['version', 'coverage', 'rto', 'rpo', 'token-count', 'translation-state', 'severity', 'level', 'type', 'status', 'count', 'size', 'duration', 'score'],
  'origin-marks': ['document', 'conversation', 'agent-from-graph', 'live-system', 'not-implemented'],
  'extractor-mark': 'extractor',
  statuses: ['implemented', 'partial', 'not-implemented'],
  'template-policies': ['page', 'member', 'none'],
} as const;

